from keyring import KeyRing
from request_model import WebhookRequest
from signature import ComparisonObserver, compare_hex, sign
from verifier import verify_webhook


SECRET = b"super-secret"


def request(signature=None, timestamp=1000, key_id="primary"):
    body = b'{"event":"invoice.paid"}'
    return WebhookRequest(key_id, timestamp, body, signature or sign(SECRET, timestamp, body))


def keys():
    return KeyRing({"primary": SECRET})


def test_valid_signature_is_accepted():
    assert verify_webhook(request(), keys(), now=1000)["ok"] is True


def test_unknown_key_is_rejected():
    assert verify_webhook(request(key_id="missing"), keys(), now=1000)["reason"] == "unknown_key"


def test_stale_timestamp_is_rejected():
    assert verify_webhook(request(timestamp=1), keys(), now=1000)["reason"] == "stale"


def test_bad_signature_is_rejected():
    assert verify_webhook(request(signature="0" * 64), keys(), now=1000)["reason"] == "bad_signature"


def test_result_keys_for_success_are_stable():
    assert set(verify_webhook(request(), keys(), now=1000)) == {"ok", "reason"}


def test_result_keys_for_failure_are_stable():
    assert set(verify_webhook(request(signature="0" * 64), keys(), now=1000)) == {"ok", "reason"}


def test_compare_checks_all_bytes_for_first_character_mismatch():
    observer = ComparisonObserver()
    compare_hex("abcdef", "zbcdef", observer)
    assert len(observer.steps) == 6


def test_compare_checks_all_bytes_for_last_character_mismatch():
    observer = ComparisonObserver()
    compare_hex("abcdef", "abcdez", observer)
    assert len(observer.steps) == 6


def test_compare_reports_true_for_equal_strings():
    assert compare_hex("abcdef", "abcdef") is True


def test_compare_reports_false_for_same_length_mismatch():
    assert compare_hex("abcdef", "abcdeg") is False


def test_compare_handles_length_mismatch_as_false():
    assert compare_hex("abcdef", "abc") is False


def test_verifier_comparison_observer_sees_full_digest_on_bad_prefix():
    observer = ComparisonObserver()
    verify_webhook(request(signature="0" + request().signature[1:]), keys(), now=1000, observer=observer)
    assert len(observer.steps) == 64


def test_common_wrong_fix_does_not_return_early_on_prefix_match_length():
    observer = ComparisonObserver()
    verify_webhook(request(signature=request().signature[:10] + "0" * 54), keys(), now=1000, observer=observer)
    assert len(observer.steps) == 64


def test_signature_changes_when_body_changes():
    assert sign(SECRET, 1000, b"a") != sign(SECRET, 1000, b"b")


def test_signature_changes_when_timestamp_changes():
    assert sign(SECRET, 1000, b"a") != sign(SECRET, 1001, b"a")


def test_keyring_can_add_key():
    ring = KeyRing({}); ring.add("k", b"s")
    assert ring.get("k") == b"s"


def test_malformed_non_ascii_signature_is_rejected():
    assert verify_webhook(request(signature="é" * 64), keys(), now=1000)["reason"] == "bad_signature"


def test_future_timestamp_outside_window_is_rejected():
    assert verify_webhook(request(timestamp=2000), keys(), now=1000)["reason"] == "stale"


def test_boundary_timestamp_inside_window_is_allowed():
    assert verify_webhook(request(timestamp=700), keys(), now=1000)["ok"] is True


def test_bad_signature_does_not_mutate_keyring():
    ring = keys(); verify_webhook(request(signature="0" * 64), ring, now=1000)
    assert ring.get("primary") == SECRET
